using Microsoft.EntityFrameworkCore;
using SmartInventory.Model.OperationsDto;
using SmartInvetory.DAL.EF;
using SmartInvetory.DAL.EF.Tables;
using SmartInvetory.DAL.Interfaces;
namespace SmartInvetory.DAL.Repository;
public class OperationsRepository : IOperationsRepository
{
 private readonly SmartInventoryDbContext _db;
 public OperationsRepository(SmartInventoryDbContext db){_db=db;}
 public List<SelectOptionDto> GetProducts()=>_db.Products.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.ProductName).Select(x=>new SelectOptionDto{Id=x.ProductId,Name=x.ProductName+" ("+x.Sku+")"}).ToList();
 public List<SelectOptionDto> GetWarehouses()=>_db.Warehouses.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.WarehouseName).Select(x=>new SelectOptionDto{Id=x.WarehouseId,Name=x.WarehouseName}).ToList();
 public List<SelectOptionDto> GetSuppliers()=>_db.Suppliers.AsNoTracking().Where(x=>x.IsActive).OrderBy(x=>x.SupplierName).Select(x=>new SelectOptionDto{Id=x.SupplierId,Name=x.SupplierName}).ToList();
 public List<SelectOptionDto> GetCustomers()=>_db.Customers.AsNoTracking().OrderBy(x=>x.CustomerName).Select(x=>new SelectOptionDto{Id=x.CustomerId,Name=x.CustomerName}).ToList();
 public List<SelectOptionDto> GetRoles()=>_db.Roles.AsNoTracking().OrderBy(x=>x.RoleName).Select(x=>new SelectOptionDto{Id=x.RoleId,Name=x.RoleName}).ToList();
 public List<StockRowDto> GetStock()=>_db.StockBalances.AsNoTracking().Include(x=>x.Product).Include(x=>x.Warehouse).Select(x=>new StockRowDto{ProductId=x.ProductId,ProductName=x.Product.ProductName,Sku=x.Product.Sku,WarehouseId=x.WarehouseId,WarehouseName=x.Warehouse.WarehouseName,Quantity=x.Quantity,ReorderLevel=x.Product.ReorderLevel}).OrderBy(x=>x.ProductName).ToList();
 public List<TransactionRowDto> GetTransactions()=>_db.StockTransactions.AsNoTracking().Include(x=>x.Product).Include(x=>x.Warehouse).OrderByDescending(x=>x.TransactionDate).Select(x=>new TransactionRowDto{Id=x.StockTransactionId,Date=x.TransactionDate,ProductName=x.Product.ProductName,WarehouseName=x.Warehouse.WarehouseName,Type=x.TransactionType,Quantity=x.Quantity,Reference=x.ReferenceNumber,Notes=x.Notes}).ToList();
 public List<OrderRowDto> GetPurchases()=>_db.PurchaseOrders.AsNoTracking().Include(x=>x.Supplier).Include(x=>x.Warehouse).OrderByDescending(x=>x.OrderDate).Select(x=>new OrderRowDto{Id=x.PurchaseOrderId,Number=x.PurchaseOrderNumber,Date=x.OrderDate,PartyName=x.Supplier.SupplierName,WarehouseName=x.Warehouse.WarehouseName,Status=x.Status,Total=x.TotalAmount}).ToList();
 public List<OrderRowDto> GetSales()=>_db.SalesOrders.AsNoTracking().Include(x=>x.Customer).Include(x=>x.Warehouse).OrderByDescending(x=>x.OrderDate).Select(x=>new OrderRowDto{Id=x.SalesOrderId,Number=x.SalesOrderNumber,Date=x.OrderDate,PartyName=x.Customer==null?"Walk-in customer":x.Customer.CustomerName,WarehouseName=x.Warehouse.WarehouseName,Status=x.Status,Total=x.TotalAmount}).ToList();
 public OrderDetailsDto? GetPurchase(int id){var x=_db.PurchaseOrders.AsNoTracking().Include(x=>x.Supplier).Include(x=>x.Warehouse).Include(x=>x.PurchaseOrderDetails).ThenInclude(x=>x.Product).FirstOrDefault(x=>x.PurchaseOrderId==id);return x==null?null:new OrderDetailsDto{Id=x.PurchaseOrderId,Number=x.PurchaseOrderNumber,Date=x.OrderDate,PartyName=x.Supplier.SupplierName,WarehouseName=x.Warehouse.WarehouseName,Status=x.Status,Total=x.TotalAmount,Notes=x.Notes,Items=x.PurchaseOrderDetails.Select(d=>new OrderDetailRowDto{ProductId=d.ProductId,ProductName=d.Product.ProductName,Quantity=d.Quantity,UnitPrice=d.UnitPrice}).ToList()};}
 public OrderDetailsDto? GetSale(int id){var x=_db.SalesOrders.AsNoTracking().Include(x=>x.Customer).Include(x=>x.Warehouse).Include(x=>x.SalesOrderDetails).ThenInclude(x=>x.Product).FirstOrDefault(x=>x.SalesOrderId==id);return x==null?null:new OrderDetailsDto{Id=x.SalesOrderId,Number=x.SalesOrderNumber,Date=x.OrderDate,PartyName=x.Customer==null?"Walk-in customer":x.Customer.CustomerName,WarehouseName=x.Warehouse.WarehouseName,Status=x.Status,Total=x.TotalAmount,Notes=x.Notes,Items=x.SalesOrderDetails.Select(d=>new OrderDetailRowDto{ProductId=d.ProductId,ProductName=d.Product.ProductName,Quantity=d.Quantity,UnitPrice=d.UnitPrice}).ToList()};}
 public bool CreatePurchase(CreateOrderDto d){ValidateCommon(d);using var tx=_db.Database.BeginTransaction();var supplier=_db.Suppliers.Find(d.PartyId)??throw new InvalidOperationException("Select a valid supplier.");var warehouse=_db.Warehouses.Find(d.WarehouseId)??throw new InvalidOperationException("Select a valid warehouse.");EnsureCreator(d.CreatedBy);var order=new PurchaseOrder{PurchaseOrderNumber="PO-"+DateTime.Now.ToString("yyyyMMddHHmmssfff"),SupplierId=supplier.SupplierId,WarehouseId=warehouse.WarehouseId,OrderDate=d.OrderDate,ExpectedDate=d.ExpectedDate,Status="Received",Notes=d.Notes,CreatedBy=d.CreatedBy,CreatedAt=DateTime.Now};foreach(var line in d.Items){var p=_db.Products.Find(line.ProductId)??throw new InvalidOperationException("Invalid product selected.");var detail=new PurchaseOrderDetail{ProductId=p.ProductId,Quantity=line.Quantity,UnitPrice=line.UnitPrice,SubTotal=line.Quantity*line.UnitPrice};order.PurchaseOrderDetails.Add(detail);order.TotalAmount+=detail.SubTotal??0;} _db.PurchaseOrders.Add(order);_db.SaveChanges();foreach(var detail in order.PurchaseOrderDetails){ChangeStock(detail.ProductId,warehouse.WarehouseId,detail.Quantity,"Purchase",order.PurchaseOrderNumber,"Purchase received",d.CreatedBy,detail.PurchaseOrderDetailId,null);} _db.SaveChanges();tx.Commit();return true;}
 public bool CreateSale(CreateOrderDto d){ValidateCommon(d);using var tx=_db.Database.BeginTransaction();var warehouse=_db.Warehouses.Find(d.WarehouseId)??throw new InvalidOperationException("Select a valid warehouse.");if(d.PartyId.HasValue&&!_db.Customers.Any(x=>x.CustomerId==d.PartyId.Value))throw new InvalidOperationException("Invalid customer selected.");EnsureCreator(d.CreatedBy);foreach(var l in d.Items){var b=_db.StockBalances.FirstOrDefault(x=>x.ProductId==l.ProductId&&x.WarehouseId==warehouse.WarehouseId);if(b==null||b.Quantity<l.Quantity)throw new InvalidOperationException("Insufficient stock for one or more products.");}var order=new SalesOrder{SalesOrderNumber="SO-"+DateTime.Now.ToString("yyyyMMddHHmmssfff"),CustomerId=d.PartyId,WarehouseId=warehouse.WarehouseId,OrderDate=d.OrderDate,Status="Completed",Notes=d.Notes,CreatedBy=d.CreatedBy,CreatedAt=DateTime.Now};foreach(var line in d.Items){var p=_db.Products.Find(line.ProductId)??throw new InvalidOperationException("Invalid product selected.");var detail=new SalesOrderDetail{ProductId=p.ProductId,Quantity=line.Quantity,UnitPrice=line.UnitPrice,SubTotal=line.Quantity*line.UnitPrice};order.SalesOrderDetails.Add(detail);order.TotalAmount+=detail.SubTotal??0;} _db.SalesOrders.Add(order);_db.SaveChanges();foreach(var detail in order.SalesOrderDetails)ChangeStock(detail.ProductId,warehouse.WarehouseId,-detail.Quantity,"Sale",order.SalesOrderNumber,"Sale completed",d.CreatedBy,null,detail.SalesOrderDetailId);_db.SaveChanges();tx.Commit();return true;}
 public bool AdjustStock(StockAdjustmentDto d){if(d.Quantity<=0)throw new InvalidOperationException("Quantity must be greater than zero.");if(d.Type!="AdjustmentIn"&&d.Type!="AdjustmentOut")throw new InvalidOperationException("Invalid adjustment type.");EnsureCreator(d.CreatedBy);using var tx=_db.Database.BeginTransaction();var delta=d.Type=="AdjustmentIn"?d.Quantity:-d.Quantity;var balance=_db.StockBalances.FirstOrDefault(x=>x.ProductId==d.ProductId&&x.WarehouseId==d.WarehouseId);if(balance==null&&delta<0)throw new InvalidOperationException("There is no stock to reduce.");if(balance!=null&&balance.Quantity+delta<0)throw new InvalidOperationException("Adjustment would make stock negative.");ChangeStock(d.ProductId,d.WarehouseId,delta,d.Type,null,d.Notes,d.CreatedBy,null,null);_db.SaveChanges();tx.Commit();return true;}
 private void ChangeStock(int productId,int warehouseId,int delta,string type,string? reference,string? notes,int userId,int? poDetail,int? soDetail){var b=_db.StockBalances.FirstOrDefault(x=>x.ProductId==productId&&x.WarehouseId==warehouseId);if(b==null){if(delta<0)throw new InvalidOperationException("Insufficient stock.");b=new StockBalance{ProductId=productId,WarehouseId=warehouseId,Quantity=0,LastUpdated=DateTime.Now};_db.StockBalances.Add(b);}if(b.Quantity+delta<0)throw new InvalidOperationException("Insufficient stock.");b.Quantity+=delta;b.LastUpdated=DateTime.Now;_db.StockTransactions.Add(new StockTransaction{ProductId=productId,WarehouseId=warehouseId,TransactionType=type,Quantity=Math.Abs(delta),ReferenceNumber=reference,Notes=notes,CreatedBy=userId,TransactionDate=DateTime.Now,PurchaseOrderDetailId=poDetail,SalesOrderDetailId=soDetail});}
 private void ValidateCommon(CreateOrderDto d){if(d.WarehouseId<=0||d.Items==null||d.Items.Count==0)throw new InvalidOperationException("Select a warehouse and add at least one product.");if(d.Items.Any(x=>x.ProductId<=0||x.Quantity<=0||x.UnitPrice<0))throw new InvalidOperationException("Each order line needs a product, positive quantity and non-negative price.");}
 private void EnsureCreator(int id){if(!_db.Users.Any(x=>x.UserId==id))throw new InvalidOperationException("A valid logged-in user is required. Set CreatedBy from the authenticated user before saving.");}
 public DashboardDto GetDashboard(){var stock=GetStock();return new DashboardDto{ProductCount=_db.Products.Count(),CategoryCount=_db.Categories.Count(),SupplierCount=_db.Suppliers.Count(),CustomerCount=_db.Customers.Count(),WarehouseCount=_db.Warehouses.Count(),LowStockCount=stock.Count(x=>x.IsLowStock),LowStock=stock.Where(x=>x.IsLowStock).Take(8).ToList(),PurchaseTotal=_db.PurchaseOrders.Where(x=>x.Status=="Received").Sum(x=>(decimal?)x.TotalAmount)??0,SalesTotal=_db.SalesOrders.Where(x=>x.Status=="Completed").Sum(x=>(decimal?)x.TotalAmount)??0,RecentTransactions=GetTransactions().Take(8).ToList()};}
 public List<UserDto> GetUsers()=>_db.Users.AsNoTracking().Include(x=>x.Role).OrderBy(x=>x.FullName).Select(x=>new UserDto{UserId=x.UserId,FullName=x.FullName,Username=x.Username,Email=x.Email,RoleId=x.RoleId,RoleName=x.Role.RoleName,IsActive=x.IsActive}).ToList();
 public UserDto? GetUser(int id)=>_db.Users.AsNoTracking().Include(x=>x.Role).Where(x=>x.UserId==id).Select(x=>new UserDto{UserId=x.UserId,FullName=x.FullName,Username=x.Username,Email=x.Email,RoleId=x.RoleId,RoleName=x.Role.RoleName,IsActive=x.IsActive}).FirstOrDefault();
 public bool SaveUser(UserDto d){if(d.UserId==0){if(string.IsNullOrWhiteSpace(d.Password))throw new InvalidOperationException("A password is required for a new user.");if(_db.Users.Any(x=>x.Username==d.Username||x.Email==d.Email))throw new InvalidOperationException("Username or email already exists.");var u=new User{FullName=d.FullName,Username=d.Username,Email=d.Email,PasswordHash=d.Password,RoleId=d.RoleId,IsActive=d.IsActive,CreatedAt=DateTime.Now};_db.Users.Add(u);}else{var u=_db.Users.Find(d.UserId);if(u==null)return false;if(_db.Users.Any(x=>x.UserId!=d.UserId&&(x.Username==d.Username||x.Email==d.Email)))throw new InvalidOperationException("Username or email already exists.");u.FullName=d.FullName;u.Username=d.Username;u.Email=d.Email;u.RoleId=d.RoleId;u.IsActive=d.IsActive;if(!string.IsNullOrWhiteSpace(d.Password))u.PasswordHash=d.Password;}return _db.SaveChanges()>0;}
 public bool DeleteUser(int id){var u=_db.Users.Find(id);if(u==null)return false;if(_db.PurchaseOrders.Any(x=>x.CreatedBy==id)||_db.SalesOrders.Any(x=>x.CreatedBy==id)||_db.StockTransactions.Any(x=>x.CreatedBy==id))throw new InvalidOperationException("This user has recorded transactions and cannot be deleted. Deactivate the account instead.");_db.Users.Remove(u);return _db.SaveChanges()>0;}
}
